'use strict';

const KEY_NAME_MAP = {
  enter: 'Enter',
  return: 'Enter',
  escape: 'Esc',
  esc: 'Esc',
  backspace: 'Backspace',
  tab: 'Tab',
  space: 'Space',
  up: 'Up',
  down: 'Down',
  left: 'Left',
  right: 'Right',
  delete: 'Delete',
  del: 'Delete',
  insert: 'Insert',
  home: 'Home',
  end: 'End',
  pageup: 'PageUp',
  pagedown: 'PageDown',
  control: 'Ctrl',
  ctrl: 'Ctrl',
  shift: 'Shift',
  alt: 'Alt',
  option: 'Alt',
  command: 'Win',
  cmd: 'Win',
  meta: 'Win'
};

function normalizeKey(key) {
  const raw = String(key || '').trim();
  if (!raw) {
    return '';
  }

  const normalized = raw.toLowerCase();
  if (KEY_NAME_MAP[normalized]) {
    return KEY_NAME_MAP[normalized];
  }

  if (normalized.length === 1 && normalized >= 'a' && normalized <= 'z') {
    return normalized.toUpperCase();
  }

  if (normalized.length === 1 && normalized >= '0' && normalized <= '9') {
    return normalized;
  }

  if (/^f([1-9]|1[0-2])$/.test(normalized)) {
    return normalized.toUpperCase();
  }

  return raw;
}

function normalizePlatform(platform) {
  return platform === 'darwin' ? 'darwin' : 'win32';
}

module.exports = {
  normalizeKey,
  normalizePlatform
};
